INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','easy','flashcard','ACE inhibitors: mechanism of action','["ACE inhibitors (e.g., lisinopril, enalapril, captopril) block angiotensin-converting enzyme (ACE/kininase II), preventing conversion of angiotensin I to angiotensin II. This reduces: (1) vasoconstriction, (2) aldosterone secretion, (3) sodium and water retention. Net effect: decreased peripheral resistance and blood volume, lowering BP. Also prevents bradykinin degradation — the cause of ACE inhibitor-related dry cough."]','A','Mnemonic: ACE inhibitors ACE the RAAS — they block the enzyme that makes Angiotensin II, so no Constriction and no Excess aldosterone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','easy','flashcard','Thiazide diuretics: mechanism and key adverse effects','["Thiazide diuretics (hydrochlorothiazide, chlorthalidone) inhibit the Na+/Cl- cotransporter in the distal convoluted tubule, increasing sodium and water excretion. Initially decrease extracellular volume; with chronic use, decrease peripheral resistance. Adverse effects: (1) Hypokalemia (K+ wasting), (2) Hyperuricemia (gout), (3) Hyperglycemia, (4) Hypercalcemia (decrease urinary Ca2+ excretion — useful in kidney stones), (5) Hyponatremia. Contraindicated: eGFR <30 mL/min (except metolazone)."]','A','5 Hs: Hypokalemia, Hyperuricemia, Hyperglycemia, Hypercalcemia, Hyperlipidemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','medium','flashcard','ARBs vs ACE inhibitors: key differences','["Both block the RAAS: ACE inhibitors block angiotensin II production; ARBs (losartan, valsartan, irbesartan) block AT1 receptors directly. Key difference: ARBs do NOT affect bradykinin metabolism, so they do NOT cause dry cough or angioedema (making them the preferred RAAS alternative when ACE inhibitor cough or angioedema occurs). Both are contraindicated in pregnancy, bilateral renal artery stenosis, and can cause hyperkalemia. Both are preferred in diabetic nephropathy and HFrEF."]','A','ARBs have the BENEFITs of ACE inhibitors Without the Bradykinin-related problems (cough, angioedema). AVOID combining ACE inhibitor + ARB (dual RAAS blockade increases AKI and hyperkalemia risk).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','medium','flashcard','Calcium channel blockers: subtypes and clinical uses','["Three subtypes: (1) Dihydropyridines (amlodipine, nifedipine, felodipine): act primarily on vascular smooth muscle — peripheral vasodilation, reduce afterload. Used in hypertension and stable angina. (2) Phenylalkylamines (verapamil): act on heart > vessels — negative inotropy, chronotropy, dromotropy. Used in arrhythmias, angina, hypertension. (3) Benzothiazepines (diltiazem): intermediate cardiac/vascular effects. Non-dihydropyridines (verapamil, diltiazem) are CONTRAINDICATED in HFrEF and combined with beta-blockers (severe AV block risk)."]','A','DHP = peripheral Dilation (amlodipine); Verapamil = cardiac (Ventricle/AV node); Diltiazem = Dual (middle).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','medium','flashcard','Beta-blockers in hypertension: mechanism and contraindications','["Beta-blockers lower BP by: (1) reducing cardiac output (decreased HR and contractility), (2) inhibiting renin release from juxtaglomerular cells (reducing angiotensin II and aldosterone), (3) decreasing central sympathetic outflow. Cardioselective (beta-1): metoprolol, atenolol, bisoprolol — safer in COPD/asthma. Non-selective (beta-1+2): propranolol, nadolol — avoid in asthma, COPD, peripheral vascular disease. Contraindications: decompensated HF, 2nd/3rd degree AV block, severe bradycardia. Abrupt withdrawal causes rebound hypertension, angina, MI."]','A','ABCD indications: After MI, Bradyarrhythmias (rate control), Chronic HF (low doses!), Diabetes (with caution).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','hard','flashcard','Hypertensive emergency: drug choices and mechanisms','["Hypertensive emergency (BP > 180/120 with end-organ damage) requires IV agents: (1) Sodium nitroprusside: releases NO → arterial and venous dilation (rapid onset/offset; cyanide toxicity risk with prolonged use). (2) Labetalol IV: alpha-1 + beta blockade; reduces HR and SVR. (3) Nicardipine IV: dihydropyridine CCB; arterial vasodilation. (4) Hydralazine IV: direct arteriolar vasodilation (used in pregnancy). (5) Clevidipine: ultra-short-acting dihydropyridine CCB. Goal: reduce MAP by 20-25% in first hour (not to normal — risk of ischemia)."]','A','Do NOT drop BP to normal immediately — cerebral, renal, coronary autoregulation has adapted to high BP. Reducing too fast causes ischemia. Rule: 20-25% reduction in MAP in first hour.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','easy','flashcard','Spironolactone: mechanism in hypertension and heart failure','["Spironolactone is an aldosterone receptor antagonist (potassium-sparing diuretic). It competitively blocks aldosterone receptors in the collecting duct, reducing Na+ reabsorption and K+ excretion. Used in: (1) resistant hypertension (add-on therapy), (2) primary hyperaldosteronism, (3) HFrEF (reduces cardiac fibrosis and remodeling — reduces mortality). Adverse effects: hyperkalemia (monitor K+), gynecomastia (anti-androgenic effect). Eplerenone is more selective, with less gynecomastia."]','A','SpiroLACTone = LACKS the ability to excrete K+ (potassium sparing). Watch for HYPERkalemia, especially with ACE inhibitors or ARBs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','hard','flashcard','Alpha-1 blockers: mechanism, use, and first-dose effect','["Alpha-1 adrenergic blockers (prazosin, doxazosin, terazosin) competitively block alpha-1 receptors on vascular smooth muscle, preventing norepinephrine-mediated vasoconstriction. Result: arterial and venous dilation, reduced SVR and BP. Clinical uses: hypertension (not first-line), benign prostatic hyperplasia (relax smooth muscle in prostate/bladder neck). First-dose orthostatic hypotension: dramatic hypotension, dizziness, syncope after first dose — patients should take at bedtime. Selective alpha-1 blockers do NOT block presynaptic alpha-2 (no reflex NE release)."]','A','First-dose effect: take at BEDTIME. Dox-a-zosin for BPH helps men pee (dox = docs prescribed it for BPH too).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','hard','flashcard','Renin-angiotensin-aldosterone system (RAAS): pharmacologic targets','["RAAS cascade: Renin → cleaves angiotensinogen → Angiotensin I → (ACE) → Angiotensin II → AT1 receptor → vasoconstriction + aldosterone secretion. Drug targets: (1) Renin inhibitors: aliskiren (directly inhibits renin). (2) ACE inhibitors: block angiotensin II production. (3) ARBs: block AT1 receptor. (4) Aldosterone antagonists: spironolactone, eplerenone. (5) Neprilysin inhibitors (sacubitril): increase natriuretic peptides. Do NOT combine ACE inhibitor + ARB (increases adverse effects without added benefit)."]','A','RAAS staircase: Renin → Ang I → Ang II → Aldosterone. Each step is a drug target. ACE inhibitors and ARBs both block angiotensin II effects but at different steps.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antihypertensives','medium','flashcard','Indications for specific antihypertensives in comorbid conditions','["Preferred antihypertensive by comorbidity: (1) Diabetic nephropathy or proteinuria: ACE inhibitor or ARB (reduce intraglomerular pressure). (2) Post-MI or stable ischemic heart disease: beta-blocker + ACE inhibitor. (3) HFrEF: ACE inhibitor/ARB, beta-blocker (carvedilol/metoprolol), spironolactone. (4) Pregnancy: methyldopa, labetalol, nifedipine (NOT ACE inhibitors/ARBs). (5) Isolated systolic hypertension in elderly: thiazide or dihydropyridine CCB. (6) Angina: beta-blocker or CCB. (7) Atrial fibrillation: beta-blocker or non-DHP CCB."]','A','Compelling indications: Match the drug to the disease. ACE inhibitor/ARB for kidney/HF; beta-blocker for post-MI/arrhythmia; CCB for elderly ISH/angina.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','easy','flashcard','Vaughan-Williams classification: overview of all 4 classes','["Class I (Na+ channel blockers): IA (quinidine, procainamide, disopyramide) — slow phase 0, prolong AP; IB (lidocaine, mexiletine) — shorten AP, fast dissociation; IC (flecainide, propafenone) — markedly slow conduction, minimal AP change. Class II (beta-blockers): metoprolol, esmolol — decrease phase 4 slope, slow AV conduction, reduce automaticity. Class III (K+ channel blockers): amiodarone, sotalol, dofetilide — prolong AP and QT. Class IV (Ca2+ channel blockers): verapamil, diltiazem — slow AV conduction. Adenosine and digoxin do not fit neatly into this classification."]','A','I Barely Can Do without Adenosine — mnemonic for antiarrhythmic classes: I (Na), II (Beta), III (K+), IV (Ca2+).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','easy','flashcard','Amiodarone: mechanism, uses, and adverse effects','["Amiodarone (Class III) primarily blocks K+ channels prolonging the action potential and refractory period. Also has Class I (Na+ channel), Class II (beta-blocker), and Class IV (Ca2+ channel) properties. Uses: ventricular tachycardia/fibrillation (drug of choice), atrial fibrillation rate/rhythm control. Adverse effects (many — mnemonic PLATE): Pulmonary toxicity (most serious), Liver toxicity, thyroid Abnormalities (hypo or hyperthyroidism — iodine-rich drug), corneal deposiTs (microdeposits), sEnsitivity (photosensitivity, blue-gray skin discoloration). Drug interactions: inhibits CYP2C9 (raises warfarin INR), CYP2D6, and P-gp (raises digoxin levels)."]','A','PLATE: Pulmonary, Liver, Abnormal thyroid, corneal deposiTs, sEnsitivity (photosensitivity). Amiodarone has everything — it works like 4 drug classes in one.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','medium','flashcard','Class IA antiarrhythmics: quinidine, procainamide, disopyramide — key differences','["All Class IA: block Na+ channels (slow phase 0), block K+ channels (prolong AP and QT). Differences: Quinidine: also has anticholinergic + alpha-blocking effects; causes cinchonism (tinnitus, blurred vision, headache, confusion) at toxic doses; metabolized by CYP3A4; inhibits CYP2D6 and P-gp. Procainamide: IV only; causes lupus-like syndrome (with long-term use); metabolized to NAPA (Class III activity). Disopyramide: most anticholinergic of the three (urinary retention, dry mouth, constipation, blurred vision); greatest negative inotropic effect; causes peripheral vasoconstriction. All three: proarrhythmic — avoid in structural heart disease."]','A','Dis-O-PYRAMIDE = most anticholinergic. ProcainAMIDE → lupus (ANA positive). QUINIDINE → cinchonism (from quinine relatives).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','medium','flashcard','Lidocaine (Class IB): mechanism, uses, pharmacokinetics','["Lidocaine rapidly associates/dissociates from Na+ channels, preferentially blocking inactivated channels in rapidly depolarizing or ischemic tissue. Also shortens phase 3 repolarization, decreasing AP duration (unlike IA which prolongs it). Uses: ventricular tachycardia (alternative to amiodarone), ventricular fibrillation (adjunct), ineffective for atrial arrhythmias (atrial tissue too short for IB effect). Must be given IV (extensive first-pass hepatic metabolism if oral — not available as oral). CNS toxicity: nystagmus (early sign), slurred speech, seizures at high doses. Metabolized by CYP1A2 (minor CYP3A4)."]','A','Lidocaine = Limited to ventricles, IV only, Leaves quickly (fast off). Nystagmus = first sign of CNS toxicity — stop the infusion!','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','medium','flashcard','Adenosine: mechanism, use, and adverse effects','["Adenosine is not in the Vaughan-Williams classification. It activates cardiac A1 (adenosine) receptors, opening K+ channels and hyperpolarizing the AV node, causing transient AV block. Used for: acute termination of AV-nodal-dependent SVT (paroxysmal SVT, AVNRT). Half-life: <10 seconds — must be given as rapid IV push followed by saline flush. Adverse effects: transient chest tightness, flushing, dyspnea, brief asystole. Contraindicated in: heart transplant (hypersensitive — denervation supersensitivity), second/third-degree AV block. Interaction: theophylline/caffeine block A1 receptors, reducing adenosine effect; dipyridamole blocks adenosine uptake, potentiating its effect."]','A','Adenosine PAUSES the AV node briefly. Half-life <10 seconds — give it FAST and FLUSH immediately. Coffee/theophylline blocks it (A1 receptor competition).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','hard','flashcard','Class IC antiarrhythmics: flecainide and propafenone — uses and contraindications','["Flecainide and propafenone slowly dissociate from Na+ channels, markedly slowing conduction in all cardiac tissue at normal heart rates. Uses: atrial fibrillation/flutter rhythm control in structurally normal hearts; paroxysmal SVT prophylaxis. Propafenone also has weak beta-blocking activity (may cause bronchospasm — avoid in asthma). CAST trial demonstrated that Class IC drugs increased mortality in patients with structural heart disease (LVH, prior MI, HF) due to proarrhythmic effects. CONTRAINDICATED in structural heart disease. Flecainide metabolized by CYP2D6."]','A','The CAST trial KILLED Class IC in structural heart disease. Use IC only in structurally NORMAL hearts. Pill-in-the-pocket strategy: flecainide for patients with AF who can self-dose at arrhythmia onset.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','hard','flashcard','Torsades de pointes: causes, drug-related risk, and management','["Torsades de pointes (TdP) is a polymorphic ventricular tachycardia associated with prolonged QT interval. Drug causes: Class IA (quinidine, procainamide), Class III (sotalol, dofetilide, amiodarone less so), other drugs (macrolide antibiotics, fluoroquinolones, antipsychotics, antiemetics). Predisposing factors: hypokalemia, hypomagnesemia, bradycardia, congenital long QT syndrome. Management: (1) IV magnesium sulfate (drug of choice — stabilizes cardiac membrane). (2) Remove offending drug. (3) Correct electrolytes (K+, Mg2+). (4) Temporary pacing to increase heart rate (shortens QT). Amiodarone is least likely of Class III to cause TdP despite prolonging QT."]','A','TdP = Twisting of Points. Treat with Mg2+ IV (Magnesium is the antidote). Predisposed by Electrolyte problems (low K+, Mg2+) and drugs that prolong QT.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','easy','flashcard','Beta-blockers as antiarrhythmics (Class II): mechanism and uses','["Class II beta-blockers (metoprolol, atenolol, esmolol, propranolol) reduce sympathetic drive to the heart: (1) Decrease automaticity (reduce slope of phase 4 depolarization in SA node), (2) Slow AV conduction (prolong PR interval), (3) Reduce heart rate and contractility. Uses: ventricular arrhythmias in post-MI patients (reduce sudden cardiac death), atrial fibrillation rate control, AV nodal reentrant tachycardia, supraventricular tachyarrhythmias. Esmolol: ultra-short-acting IV beta-blocker (metabolized by red blood cell esterases), used in acute/perioperative settings."]','A','Class II = Beat Blockers (Beta-Blockers). Esmolol is the Emergency beta-blocker (IV, ultra-short).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','hard','flashcard','Digoxin in arrhythmia management: mechanism and toxicity','["Digoxin slows AV nodal conduction by enhancing vagal (parasympathetic) tone to the AV node and directly inhibiting Na+/K+-ATPase. Used for rate control in atrial fibrillation (not rhythm control). Digoxin toxicity: narrow therapeutic index. Symptoms: GI (nausea, vomiting, anorexia), neurological (yellow-green visual halos, xanthopsia, confusion), cardiac (bradycardia, AV block, premature ventricular contractions, ventricular tachycardia in severe toxicity). Precipitating factors: hypokalemia (K+ competes with digoxin at Na+/K+-ATPase), hypomagnesemia, renal impairment. Treatment: digoxin-specific antibody fragments (Digibind/DigiFab) for severe toxicity."]','A','Yellow-green halos + bradycardia + nausea = digoxin toxicity. Low K+ = MORE toxic (less competition for binding site). Treat with Digibind.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiarrhythmics','medium','flashcard','Sotalol: classification and distinguishing features','["Sotalol has BOTH Class II (non-selective beta-blocker) and Class III (K+ channel blocker) properties. As Class III: prolongs action potential and QT interval. As Class II: decreases heart rate and AV conduction. Uses: ventricular arrhythmias, maintenance of sinus rhythm in atrial fibrillation/flutter. Adverse effects: QT prolongation → torsades de pointes (more pronounced than amiodarone); bradycardia; bronchospasm (non-selective beta-blocker). Requires renal dose adjustment (primarily renally excreted). Initiation requires hospitalization for QT monitoring."]','A','Sotalol = BOTH a beta-blocker (Class II) AND K+ channel blocker (Class III). Must initiate in hospital with telemetry monitoring due to QT prolongation and TdP risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','easy','flashcard','Goals and drug classes in HFrEF treatment','["HFrEF treatment goals: relieve symptoms, prevent disease progression, reduce mortality. Mortality-reducing drug classes (4 pillars of HFrEF): (1) ACE inhibitor/ARB or ARNI (sacubitril/valsartan) — reduce RAAS-mediated remodeling. (2) Beta-blockers (carvedilol, metoprolol succinate, bisoprolol) — reduce sympathetic remodeling. (3) Mineralocorticoid antagonists (spironolactone, eplerenone) — reduce aldosterone-mediated fibrosis. (4) SGLT2 inhibitors (dapagliflozin, empagliflozin) — reduce HF hospitalizations and mortality. Symptom relief: loop diuretics (furosemide) for congestion. Digoxin reduces hospitalizations but not mortality."]','A','4 pillars of HFrEF: ACE/ARB/ARNI + Beta-blocker + MRA + SGLT2i. Add loop diuretic for symptoms. Mnemonic: All Brave Men Should.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','easy','flashcard','Digoxin in heart failure: mechanism and clinical role','["Digoxin inhibits Na+/K+-ATPase in cardiac myocytes, increasing intracellular Na+, which reduces Na+/Ca2+ exchanger activity, leading to increased intracellular Ca2+ and positive inotropy (increased contractility). Also enhances vagal tone (slows AV conduction — useful for rate control in AF with HF). Clinical role in HF: reduces symptoms and hospitalizations in HFrEF; does NOT reduce mortality. Narrow therapeutic index — target serum level 0.5-0.9 ng/mL (lower range reduces mortality; higher range increases it). Hypokalemia and hypomagnesemia increase toxicity risk."]','A','Digoxin: Na/K pump inhibitor → more Ca2+ inside → stronger squeeze (positive inotropy). Does NOT save lives but does reduce HF hospitalizations. Toxic at high levels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','medium','flashcard','Loop diuretics in heart failure: mechanism and monitoring','["Furosemide, torsemide, and bumetanide inhibit the Na+/K+/2Cl- cotransporter (NKCC2) in the thick ascending limb of the loop of Henle, producing potent natriuresis and diuresis. Reduce preload by decreasing circulating blood volume. Also cause renal venodilation (reducing renal congestion). Monitoring: serum K+ (hypokalemia — most important, can precipitate digoxin toxicity and arrhythmias), serum Na+, creatinine (adequate renal perfusion), and daily weight. IV furosemide is first-line for acute decompensated HF. Torsemide has better bioavailability (~80%) than furosemide (~50%, variable)."]','A','Furosemide = First-line diuretic in decompensated HF. FURosemide = FURious diuresis. Monitor K+, Na+, creatinine, and daily weights.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','medium','flashcard','Sacubitril/valsartan (ARNI): mechanism and advantages over ACE inhibitors in HFrEF','["Sacubitril/valsartan (Entresto) = Neprilysin inhibitor + ARB. Sacubitril inhibits neprilysin (enzyme that degrades natriuretic peptides BNP, ANP, and bradykinin), increasing these vasodilatory/natriuretic peptides. Valsartan blocks AT1 receptors. Combined effect: vasodilation, natriuresis, anti-fibrotic effects. PARADIGM-HF trial: sacubitril/valsartan superior to enalapril in reducing HF mortality and hospitalizations in HFrEF (EF <40%). Caution: NEVER combine with ACE inhibitor (risk of angioedema from bradykinin accumulation); 36-hour washout required when switching from ACE inhibitor to ARNI."]','A','ARNI = ARB + Neprilysin Inhibitor. Must STOP ACE inhibitor 36 hours before starting (dual bradykinin accumulation → angioedema). ARNI > ACE inhibitor in HFrEF outcomes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','medium','flashcard','Ivabradine: mechanism and indication in heart failure','["Ivabradine selectively inhibits the hyperpolarization-activated cyclic nucleotide-gated (HCN) channel (I_f, the ''''funny current'''') in the SA node pacemaker cells. This reduces the slope of phase 4 depolarization, slowing heart rate WITHOUT affecting contractility, BP, or AV conduction. Indication in HFrEF: adjunct when resting HR ≥70 bpm despite maximally tolerated beta-blocker dose (or when beta-blockers are contraindicated), in patients with sinus rhythm. Adverse effects: symptomatic bradycardia, phosphenes (visual light flashes), contraindicated in acute decompensated HF."]','A','Ivabradine targets the If (funny) current — it slows the FUNNY pacemaker. Heart rate goes down but squeeze (contractility) stays the same. Only for SINUS rhythm (does not work in AF).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','hard','flashcard','RAAS, SNS, and cardiac remodeling in HF: why neurohormonal blockade improves outcomes','["In HF, decreased cardiac output activates compensatory responses: (1) Sympathetic nervous system → increased heart rate, contractility, SVR — chronically causes myocyte hypertrophy, fibrosis, beta-1 receptor downregulation. (2) RAAS → angiotensin II causes vasoconstriction and aldosterone secretion → sodium retention, volume overload, further remodeling. (3) Aldosterone → promotes myocardial fibrosis and collagen deposition. Pharmacologic neurohormonal blockade: ACE inhibitors/ARBs reduce angiotensin II and aldosterone → decrease preload/afterload + prevent remodeling. Beta-blockers → block catecholamine-mediated remodeling, allow beta-1 receptor upregulation over weeks. Spironolactone → prevents aldosterone-mediated fibrosis. These interventions reverse maladaptive remodeling = reverse remodeling."]','A','Chronic HF = maladaptive SNS + RAAS activation. Block both with beta-blockers + ACE inhibitors/ARBs + MRA. The heart REMODELS BACK toward normal with treatment over months.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','hard','flashcard','Hydralazine/isosorbide dinitrate combination in heart failure','["Hydralazine directly relaxes arteriolar smooth muscle (exact mechanism unclear, possibly inhibits IP3-mediated Ca2+ release) — arterial vasodilator reducing afterload (SVR). Isosorbide dinitrate donates NO → cGMP → venous dilation, reducing preload (LVEDP). Together they reduce both preload and afterload in HF. Evidence: V-HeFT I trial showed mortality benefit. African-American patients with HFrEF (BiDil trial): combination added to standard therapy significantly reduces mortality. Current indication: alternative when ACE inhibitor/ARB not tolerated; self-identified African-Americans with HFrEF already on optimal therapy."]','A','Hydralazine = Arteries (afterload). Nitrates = Veins (preload). Together: A+V = Arteriovenous dilation. Specifically proven in African-American HFrEF patients (BiDil study).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','easy','flashcard','Inotropic agents in acute decompensated heart failure','["Positive inotropes increase myocardial contractility for acute/severe HF (cardiogenic shock): (1) Dobutamine: beta-1 agonist; increases cAMP → increased Ca2+ → increased contractility; also has mild beta-2 (vasodilation) and mild alpha effects. (2) Milrinone: PDE-3 inhibitor; prevents cAMP breakdown in cardiac and vascular smooth muscle → positive inotropy + vasodilation (''''inodilator''''). (3) Dopamine: dose-dependent effects — low dose (renal perfusion), medium dose (beta-1 inotropy), high dose (alpha-1 vasoconstriction). Adverse effect of all: increased myocardial oxygen demand, arrhythmias. Reserved for short-term use only — long-term inotrope use increases mortality."]','A','DOBUTamine = DOes the heart Beat harder (beta-1). MILrinone = MILd dilation + inotropy (PDE-3 inhibitor). Short-term use only — increases mortality long-term.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','hard','flashcard','Beta-blockers in chronic HFrEF: paradox and evidence','["Paradox: beta-blockers are negative inotropes, yet they reduce mortality in HFrEF. Explanation: chronic sympathetic activation causes: (1) beta-1 receptor downregulation, (2) myocyte hypertrophy and apoptosis, (3) arrhythmias. Beta-blockers block these maladaptive effects over weeks-months. MUST start at LOW doses when patient is euvolemic (compensated HF) and titrate slowly. Three proven beta-blockers: carvedilol (alpha-1 + beta-1 + beta-2), metoprolol succinate (beta-1 selective), bisoprolol (beta-1 selective). CONTRAINDICATED in acute decompensated HF."]','A','The HF Paradox: Beta-blockers HURT acutely but HELP chronically. Start LOW, go SLOW. Only use when patient is DRY (compensated). Three proven agents: Carvedilol, Metoprolol succinate, Bisoprolol = CMB.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Heart Failure Pharmacotherapy','medium','flashcard','Mineralocorticoid antagonists in HFrEF: spironolactone and eplerenone','["Spironolactone and eplerenone are competitive aldosterone receptor antagonists. In HFrEF they: (1) reduce aldosterone-mediated cardiac fibrosis and collagen deposition (independent of diuretic effect), (2) modest diuresis with potassium retention. Evidence: RALES trial (spironolactone) and EMPHASIS-HF (eplerenone) both showed ~30% mortality reduction in HFrEF. Adverse effects: hyperkalemia (monitor K+, especially with ACE inhibitor), gynecomastia/sexual dysfunction with spironolactone (eplerenone is more selective, avoids steroid side effects). Contraindicated: eGFR <30 mL/min or K+ >5 mEq/L."]','A','Spironolactone saves hearts by blocking FIBROSIS (not just as a diuretic). RALES trial: 30% mortality reduction. Watch K+ — can cause dangerous hyperkalemia with ACE inhibitors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','easy','flashcard','Nitrates: mechanism of action in angina','["Organic nitrates (nitroglycerin, isosorbide dinitrate, isosorbide mononitrate) are converted to nitric oxide (NO) in vascular smooth muscle. NO activates soluble guanylyl cyclase → increases cGMP → activates protein kinase G → dephosphorylates myosin light chain → smooth muscle relaxation. Primary effects: (1) Venous dilation (reduces preload, LVEDP, wall stress) — main effect at low doses. (2) Coronary artery dilation (improves perfusion, dilates collaterals). (3) Arterial dilation at higher doses (reduces afterload). Sublingual nitroglycerin: onset 1-3 minutes (bypasses first-pass metabolism), duration ~30 minutes. Use: acute angina relief and prophylaxis."]','A','Nitrates → NO → cGMP → smooth muscle relaxes. Veins first (preload↓), then arteries (afterload↓) at higher doses. SL nitroglycerin is the fastest relief (30 min duration).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','easy','flashcard','Beta-blockers in stable angina: mechanism of benefit','["Beta-blockers reduce myocardial oxygen demand (MVO2) by: (1) Decreasing heart rate → prolongs diastole (more time for coronary perfusion), (2) Decreasing contractility (force), (3) Decreasing systolic wall stress (afterload reduction at exercise). First-line for stable angina (especially with post-MI or HFrEF). Benefit in exercise-induced angina: blunt the sympathetic surge during exercise that increases HR and MVO2. Do NOT use non-selective beta-blockers in vasospastic (Prinzmetal) angina — unopposed alpha-mediated coronary vasoconstriction can worsen spasm. Preferred agents: metoprolol, atenolol, bisoprolol."]','A','Beta-blockers = Brake pedal for the heart. Lower HR, less force, less oxygen needed. Diastole lasts longer = more blood into coronary arteries (they fill in diastole). Do NOT use in Prinzmetal (vasospastic) angina.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','medium','flashcard','Ranolazine: unique mechanism and clinical use','["Ranolazine inhibits the late inward sodium current (late I_Na) that is activated during myocardial ischemia. Normally, ischemia prolongs Na+ channel opening, increasing intracellular Na+, which reduces Na+/Ca2+ exchanger efficiency, leading to intracellular Ca2+ overload and diastolic dysfunction. Ranolazine blocks this late Na+ current, reducing intracellular Ca2+ overload, improving diastolic relaxation and microvascular perfusion, without significantly affecting heart rate or blood pressure. Approved as adjunct for chronic stable angina when other agents are inadequate. Metabolized by CYP3A4. Prolongs QT interval slightly."]','A','Ranolazine = unique mode: blocks LATE Na current (not early). Ischemia → late Na current open → Na+ → Ca2+ overload → poor relaxation. Ranolazine fixes this without slowing heart rate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','medium','flashcard','Calcium channel blockers in angina: dihydropyridines vs non-dihydropyridines','["Dihydropyridines (amlodipine, nifedipine): primarily vascular smooth muscle → coronary and peripheral vasodilation → reduce afterload and increase myocardial O2 supply. First-line for vasospastic (Prinzmetal) angina. Risk: reflex tachycardia (short-acting nifedipine) — use long-acting formulations. Non-dihydropyridines (verapamil, diltiazem): cardiac > vascular effects → reduce HR, contractility, and AV conduction in addition to coronary dilation. Reduce both MVO2 and increase supply. Preferred when beta-blockers are contraindicated. AVOID non-DHP CCBs in: HFrEF (negative inotropy), WPW + AF (may enhance conduction through accessory pathway), beta-blocker combination (severe AV block)."]','A','DHP CCBs = vascular (coronary dilation). Non-DHP CCBs = vascular + heart rate (like adding a soft beta-blocker). Non-DHP = NOT for HFrEF or bradycardia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','easy','flashcard','Nitrate tolerance: mechanism and how to prevent it','["Nitrate tolerance: loss of antianginal effectiveness with continuous nitrate use within 24-48 hours. Mechanism: (1) Depletion of intracellular sulfhydryl (-SH) groups required for NO generation from nitrates. (2) Neurohormonal counterregulation (activation of RAAS and sympathetic system from vasodilation). (3) Increased oxidative stress. Prevention: Nitrate-free interval of 8-12 hours per day (typically overnight, when angina is least common). Patients on long-acting nitrates should have asymmetric dosing (e.g., ISDN 3x/day: 7am, 12pm, 5pm — leaving overnight nitrate-free). N-acetylcysteine (replenishes SH groups) or ACE inhibitors may attenuate tolerance."]','A','Tolerance = the drug stops working. PREVENT by giving patients a BREAK (nitrate-free interval of 8-12 hours, usually overnight). Mnemonic: even nitroglycerin needs sleep.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','hard','flashcard','Unstable angina vs stable angina: pharmacologic differences','["Stable angina (effort-induced): caused by fixed coronary stenosis; relieved by rest or SL nitroglycerin; treated with: beta-blockers, long-acting nitrates, CCBs, ranolazine, aspirin. Unstable angina (UA): part of ACS; due to plaque rupture + thrombus (not fixed stenosis); NOT fully relieved by rest; requires: antiplatelet therapy (aspirin + P2Y12 inhibitor), anticoagulation (heparin or LMWH), nitrates IV, oxygen if hypoxic, beta-blockers, possible PCI. Dipyridamole is CONTRAINDICATED in unstable angina (coronary steal: vasodilation of non-ischemic vessels diverts blood from ischemic regions)."]','A','UA = ACS = plaque rupture = need dual antiplatelet + anticoagulation + possible PCI. Stable angina = fixed lesion = optimize medical therapy first. Dipyridamole is contraindicated in UA (coronary steal).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','medium','flashcard','PDE-5 inhibitors and nitrate interaction: absolute contraindication','["PDE-5 inhibitors (sildenafil, tadalafil, vardenafil, avanafil) inhibit phosphodiesterase-5, which degrades cGMP in vascular smooth muscle. Nitrates increase cGMP production via NO. Combined: massive cGMP accumulation → profound systemic vasodilation → severe hypotension → cardiovascular collapse (potentially fatal). This combination is ABSOLUTELY contraindicated. Timing: avoid nitrates for 24 hours after sildenafil/vardenafil; 48 hours after tadalafil (longer half-life). If a patient on a PDE-5 inhibitor presents with ACS and needs nitrates, this combination must be avoided; consider other therapies (IV fluids if hemodynamically unstable)."]','A','PDE5 inhibitor + Nitrate = DEATH by double cGMP. Tell every patient on nitrates to NEVER take Viagra/Cialis/Levitra. Ask about PDE5 inhibitor use before giving SL NTG in chest pain.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','hard','flashcard','Prinzmetal (vasospastic) angina: pathophysiology and management','["Prinzmetal angina: caused by coronary artery vasospasm (not fixed atherosclerotic stenosis). Occurs at rest, often in early morning. ECG: ST elevation (transient) during spasm, unlike stable angina (ST depression). Triggers: hyperventilation, cocaine, cold exposure. Management: (1) Calcium channel blockers (first-line): amlodipine, diltiazem — relax coronary smooth muscle. (2) Nitrates (long-acting): reduce vasospasm. (3) AVOID non-selective beta-blockers (propranolol, nadolol): may worsen spasm by blocking beta-2 vasodilation and leaving alpha-mediated constriction unopposed. (4) AVOID cocaine (major trigger). Diagnosis: provocation test with ergonovine or acetylcholine (induces spasm in cath lab)."]','A','Prinzmetal = Spasm of coronary artery. TREAT with CCBs and nitrates. AVOID non-selective beta-blockers (worsen spasm). ST ELEVATION during attack (unlike stable angina).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','hard','flashcard','Acute coronary syndrome (ACS) pharmacotherapy: overview','["ACS management targets: (1) Reperfusion: primary PCI preferred; thrombolytics if PCI unavailable within 120 min (STEMI). (2) Antiplatelets: aspirin (loading 325 mg) + P2Y12 inhibitor (clopidogrel, ticagrelor, or prasugrel). (3) Anticoagulation: unfractionated heparin or LMWH (enoxaparin) or fondaparinux or bivalirudin. (4) Nitrates: IV nitroglycerin for ongoing ischemia (avoid in RV infarct, hypotension, PDE5 inhibitor use). (5) Beta-blockers: start within 24h if no contraindication (reduce HR, wall stress, infarct size). (6) ACE inhibitor: start within 24-48h (reduce remodeling post-MI). (7) Statin: high-intensity immediately. (8) Morphine: for pain (used cautiously, may decrease antiplatelet absorption)."]','A','ACS memory: MONA-BASH (Morphine, O2, Nitrates, Aspirin + Beta-blocker, ACE inhibitor, Statin, Heparin). Primary PCI is better than thrombolytics if available within 90-120 min.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antianginals','easy','flashcard','Sublingual nitroglycerin: dosing, storage, and counseling points','["Sublingual nitroglycerin (SL NTG) 0.3-0.4 mg tablet or spray for acute angina: (1) Sit or lie down before use (prevents falls from hypotension). (2) May repeat every 5 minutes for a total of 3 doses. (3) If no relief after 3 doses → call emergency services (may be MI). (4) Storage: in original dark glass bottle, tightly sealed, away from heat and light — NTG degrades rapidly with exposure to light, heat, and moisture. Replace every 3-6 months. (5) Do NOT swallow (first-pass metabolism destroys it). (6) Common adverse effects: headache (most common), flushing, dizziness, hypotension."]','A','The 3-5-3 rule: 3 tablets, 5 min apart, call 911 after 3rd dose if no relief. Store in DARK glass bottle (nitroglycerin is sensitive to light). Headache = normal side effect (vasodilation of meningeal vessels).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','easy','flashcard','Statins: mechanism, potency ranking, and key adverse effects','["Statins competitively inhibit HMG-CoA reductase, the rate-limiting enzyme in cholesterol synthesis. Reduced intracellular cholesterol → upregulation of LDL receptors on hepatocytes → increased LDL-C clearance from plasma. Potency (LDL-lowering): rosuvastatin ≥ atorvastatin > pitavastatin > simvastatin > lovastatin > pravastatin > fluvastatin. Also modestly lower triglycerides and raise HDL. Pleiotropic effects: anti-inflammatory, plaque stabilization, anti-thrombotic. Adverse effects: myopathy/myalgia (most common), rhabdomyolysis (rare but serious — check CK if muscle symptoms), elevated liver enzymes (check LFTs before starting), new-onset diabetes (modest risk). CONTRAINDICATED: pregnancy (category X), active liver disease, concomitant gemfibrozil (rhabdomyolysis risk)."]','A','Rosuvastatin and Atorvastatin = Most potent (RA = Ridiculously Able). Pravastatin is least CYP450-dependent (safer with interacting drugs). Statins = standard of care for ASCVD risk reduction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','easy','flashcard','PCSK9 inhibitors: mechanism and clinical role','["PCSK9 (proprotein convertase subtilisin kexin type 9) is a liver-secreted enzyme that binds to LDL receptors and directs them toward lysosomal degradation, reducing LDL-receptor density on hepatocytes. PCSK9 inhibitors (alirocumab [Praluent], evolocumab [Repatha]) are fully humanized monoclonal antibodies that bind and neutralize PCSK9, preventing LDL receptor degradation → more LDL receptors available → dramatic LDL-C reduction (50-70% on top of statins). Indications: (1) Familial hypercholesterolemia (heterozygous or homozygous), (2) Clinical ASCVD with inadequate LDL-C control on maximal statin + ezetimibe. Route: subcutaneous injection every 2-4 weeks. Well tolerated; injection site reactions most common."]','A','PCSK9 destroys LDL receptors. Block PCSK9 → more receptors → liver removes more LDL from blood. Reduction of 50-70% LDL-C. Injected every 2-4 weeks. Very expensive.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','medium','flashcard','Fibrates: mechanism, uses, and drug interactions','["Fibrates (gemfibrozil, fenofibrate) are PPAR-alpha (peroxisome proliferator-activated receptor alpha) agonists. Activation of PPAR-alpha: (1) Increases lipoprotein lipase (LPL) expression → increased VLDL hydrolysis → decreased triglycerides (20-50% reduction). (2) Decreases apoC-III (an LPL inhibitor) → further TG reduction. (3) Increases apo-AI and apo-AII → increased HDL-C. Primary use: severe hypertriglyceridemia (TG > 500 mg/dL, pancreatitis prevention); type III hyperlipidemia (dysbetalipoproteinemia). Drug interaction: gemfibrozil + statin (especially simvastatin) → markedly increased rhabdomyolysis risk (gemfibrozil inhibits OATP1B1 and UGT, raising statin levels). Fenofibrate has less of this interaction."]','A','Fibrates = FIRE triglycerides (reduce TG by 20-50%). PPAR-alpha activators. DANGER: Gemfibrozil + statin = rhabdomyolysis risk. Fenofibrate is safer with statins.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','medium','flashcard','Ezetimibe: mechanism and place in therapy','["Ezetimibe selectively inhibits the NPC1L1 (Niemann-Pick C1-Like 1) cholesterol transporter in the brush border of intestinal enterocytes, blocking absorption of both dietary and biliary cholesterol. This reduces hepatic cholesterol supply, causing upregulation of hepatic LDL receptors. LDL-C reduction: 15-25% (modest as monotherapy; more useful as adjunct to statins). IMPROVE-IT trial: ezetimibe added to simvastatin reduced cardiovascular events further than simvastatin alone in patients post-ACS. Primary use: (1) Adjunct to statins in high-risk patients, (2) Statin-intolerant patients. Metabolized primarily by glucuronidation in the intestine and liver; not significantly CYP450 metabolized."]','A','Ezetimibe BLOCKS cholesterol from entering at the gut border (NPC1L1). Modest alone but ADDS to statins. IMPROVE-IT proved it works: statin + ezetimibe > statin alone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','medium','flashcard','Niacin (nicotinic acid): mechanism and adverse effects','["Niacin (at gram doses) strongly inhibits hormone-sensitive lipase in adipose tissue, reducing lipolysis and free fatty acid (FFA) release. Less FFA to liver → decreased hepatic VLDL synthesis → decreased VLDL and LDL-C. Also increases HDL-C (most effective agent — raises HDL by 15-35%) by reducing HDL apolipoprotein catabolism. Lowers TG by 20-35%. Adverse effects: (1) Cutaneous flushing (prostaglandin D2-mediated — reduce with aspirin 30 min before, or with extended-release formulation). (2) Hyperuricemia and gout (inhibits tubular uric acid secretion). (3) Hepatotoxicity (with sustained-release forms especially). (4) Hyperglycemia (impairs insulin sensitivity). (5) GI upset."]','A','Niacin = Nicotinic acid. Best at raising HDL. Flushing = PGD2 mediated → aspirin 30 min before blunts it. Niacin causes gout (blocks uric acid secretion) and raises glucose.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','hard','flashcard','Bile acid sequestrants: mechanism, benefits, and limitations','["Bile acid sequestrants (cholestyramine, colestipol, colesevelam) are large anion-exchange resins that bind negatively charged bile acids in the intestinal lumen, interrupting enterohepatic circulation. Consequence: liver converts more cholesterol → bile acids (to replenish supply) → depletes hepatic cholesterol → upregulates LDL receptors → decreased plasma LDL-C (15-30%). Benefits: very safe (not absorbed), can be used in pregnancy, children, and statin-intolerant patients. Colesevelam also approved for type 2 diabetes (modest glucose-lowering). Limitations: (1) Raise triglycerides (contraindicated if TG > 400 mg/dL). (2) Impair absorption of fat-soluble vitamins (A, D, E, K) and many drugs (digoxin, warfarin, thyroid hormone, statins) — other drugs should be taken 1-2 h before or 4-6 h after. (3) GI side effects (bloating, constipation)."]','A','Bile acid sequestrants TRAP bile acids in the gut → liver uses more cholesterol to make new bile → LDL receptors go up. Cannot absorb vitamins or other drugs properly. TG goes UP — avoid in hypertriglyceridemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','hard','flashcard','Statin drug interactions: CYP3A4 inhibitors and rhabdomyolysis risk','["Most statins (simvastatin, lovastatin, atorvastatin) are metabolized by CYP3A4. Drugs that inhibit CYP3A4 increase statin plasma levels and rhabdomyolysis risk: azole antifungals (itraconazole, ketoconazole), macrolide antibiotics (clarithromycin, erythromycin), HIV protease inhibitors (ritonavir), grapefruit juice (intestinal CYP3A4 inhibitor), cyclosporine. Simvastatin/lovastatin + CYP3A4 inhibitor: highest risk. Pravastatin: NOT metabolized by CYP450 (sulfation) — safest with CYP3A4 inhibitors. Rosuvastatin: minimal CYP3A4, metabolized by CYP2C9. Also avoid: gemfibrozil with any statin (pharmacokinetic interaction via OATP1B1 and UGT inhibition). Monitor CK in patients with muscle symptoms."]','A','Safe statin with CYP3A4 inhibitors = PRAVastatin (no CYP450) or ROSUvastatin (CYP2C9, not 3A4). Simvastatin = most dangerous with CYP3A4 inhibitors (dose capped at 20mg with some CYP3A4 inhibitors).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','easy','flashcard','Four statin benefit groups per ACC/AHA guidelines','["ACC/AHA 2013 guidelines identify 4 statin benefit groups: (1) Patients with clinical ASCVD (history of MI, stroke, PAD, coronary revascularization) → high-intensity statin. (2) Primary hypercholesterolemia with LDL-C ≥190 mg/dL → high-intensity statin. (3) Diabetes aged 40-75 with LDL-C 70-189 mg/dL → moderate-intensity statin; high-intensity if 10-year ASCVD risk ≥7.5%. (4) Primary prevention: age 40-75, LDL-C 70-189 mg/dL, 10-year ASCVD risk ≥7.5% → moderate to high-intensity statin. High-intensity statins: atorvastatin 40-80 mg, rosuvastatin 20-40 mg. Moderate-intensity: simvastatin 20-40 mg, atorvastatin 10-20 mg, pravastatin 40-80 mg."]','A','4 Statin Benefit Groups: (1) ASCVD history, (2) LDL ≥190, (3) Diabetics 40-75, (4) 10-year risk ≥7.5%. When in doubt, calculate the ASCVD 10-year risk score.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','hard','flashcard','Familial hypercholesterolemia: pathophysiology and drug management','["Familial hypercholesterolemia (FH): genetic defect in LDL receptor (most common: heterozygous), resulting in markedly elevated LDL-C (250-550 mg/dL in HeFH; >600 mg/dL in HoFH). Manifestations: tendon xanthomas, corneal arcus, premature ASCVD. Drug therapy: (1) High-intensity statin (first-line) — reduces LDL ~50%. (2) Ezetimibe — adds 15-25% reduction. (3) PCSK9 inhibitors — reduces LDL 50-70% further. (4) Bile acid sequestrants — adjunct. (5) Mipomersen (apolipoprotein B synthesis inhibitor — HoFH). (6) Lomitapide (MTP inhibitor reduces chylomicron/VLDL assembly — HoFH). (7) LDL apheresis for HoFH. Statins less effective in HoFH (lack functional LDL receptors to upregulate)."]','A','FH = no LDL receptors → LDL cannot be cleared. Treatment staircase: Statin → +Ezetimibe → +PCSK9 inhibitor → possibly LDL apheresis. HoFH is hardest to treat (no receptors to upregulate).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Lipid-Lowering Agents','medium','flashcard','Omega-3 fatty acids in dyslipidemia','["High-dose prescription omega-3 fatty acids (icosapentaenoic acid [EPA] and docosahexaenoic acid [DHA]) significantly reduce triglycerides (by 30-50%) at doses of 3-4 g/day. Mechanism: reduce hepatic VLDL production (reduce de novo lipogenesis and increase hepatic fatty acid beta-oxidation). Pure EPA (icosapentaenoic acid / IPE; brand: Vascepa): REDUCE-IT trial demonstrated 25% relative risk reduction of ASCVD events in patients with elevated TG (≥150 mg/dL) on statins. EPA+DHA combinations (Lovaza): lower TG but may raise LDL-C slightly. Adverse effects: fishy taste/belching, GI upset, increased bleeding time (antiplatelet effect). Use with caution with anticoagulants."]','A','High-dose omega-3s = prescription only for TG lowering. Vascepa (pure EPA) reduces heart attacks in high-TG patients on statins (REDUCE-IT trial). Fish oil in high doses = real medicine.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','easy','flashcard','Heparin: mechanism, monitoring, and reversal','["Unfractionated heparin (UFH) binds antithrombin III (ATIII), accelerating ATIII-mediated inhibition of thrombin (factor IIa) and factor Xa ~1000-fold. Also inactivates factors IXa, Xa, XIa, XIIa. Administered: IV or subcutaneous (not oral — large negatively charged molecule). Monitoring: activated partial thromboplastin time (aPTT) — target 1.5-2.5x normal; or anti-Xa levels. Onset: immediate (IV). Half-life: ~1.5 hours. Reversal: protamine sulfate (positively charged protein binds negatively charged heparin ionically in 1:1 complex; dose: 1 mg per 100 units of heparin administered). Adverse effects: bleeding, HIT (immune-mediated thrombocytopenia + thrombosis — stop heparin immediately), osteoporosis (long-term)."]','A','Heparin → turbocharges ATIII. Monitor with aPTT. Reverse with protamine sulfate. HIT = Heparin-Induced Thrombocytopenia = stop heparin, start argatroban (non-heparin anticoagulant).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','easy','flashcard','Warfarin: mechanism, monitoring, and reversal','["Warfarin inhibits vitamin K epoxide reductase, preventing regeneration of reduced (active) vitamin K. Without reduced vitamin K, clotting factors II, VII, IX, X (and protein C and S) cannot be gamma-carboxylated and remain inactive. Onset: delayed (72-96 hours to deplete existing factors; factor VII has shortest half-life — affected first). Monitoring: INR (international normalized ratio) — target usually 2-3 (higher for mechanical heart valves). Drug interactions: extensive (CYP2C9 substrate — inhibitors raise INR, inducers lower INR). Reversal: (1) Hold warfarin, (2) Oral vitamin K (24h reversal), (3) IV vitamin K (faster), (4) FFP or 4-factor PCC (prothrombin complex concentrate) for immediate/life-threatening reversal."]','A','Warfarin blocks vitamin K recycling → factors II, VII, IX, X inactive. Monitor INR. Reverse with vitamin K (slow) or FFP/PCC (fast). Factor VII affected first (shortest half-life).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','medium','flashcard','LMWHs vs UFH: key clinical differences','["LMWH (enoxaparin, dalteparin, tinzaparin): produced by depolymerizing UFH. Key differences from UFH: (1) More predictable pharmacokinetics (less protein binding) → weight-based dosing, no routine aPTT monitoring. (2) Predominantly inactivate factor Xa (not thrombin) — too short to form ternary complex with ATIII+thrombin. (3) Subcutaneous only (except enoxaparin which can be IV for STEMI). (4) Longer half-life (3-12 hours vs ~1.5 h for UFH). (5) Renal elimination — reduce dose in CrCl <30 mL/min. (6) Less HIT risk than UFH (but CANNOT use in HIT — cross-reactive antibodies). (7) Reversal: protamine partially reverses (LMWH anti-Xa activity partially reversed). Safe in pregnancy (does not cross placenta)."]','A','LMWH = Low Maintenance: no aPTT monitoring, subcutaneous, predictable. But reduce dose in renal failure (renally cleared). CANNOT use in HIT (cross-reactive).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','medium','flashcard','DOACs: mechanism, monitoring, and reversal agents','["Direct Oral Anticoagulants (DOACs): (1) Dabigatran (Pradaxa): direct thrombin (IIa) inhibitor; reversal = idarucizumab (monoclonal antibody fragment). (2) Rivaroxaban (Xarelto), Apixaban (Eliquis), Edoxaban (Savaysa): direct factor Xa inhibitors; reversal = andexanet alfa (recombinant Xa decoy). Advantages over warfarin: no routine monitoring, fewer drug interactions, fixed dosing, faster onset/offset. Disadvantages: renal clearance (especially dabigatran — avoid CrCl <30 mL/min), cost, no reliable routine lab test for monitoring (anti-Xa or dTT for emergencies). Contraindicated: mechanical prosthetic heart valves (dabigatran), severe renal impairment (especially dabigatran). Dabigatran: GI side effects common, requires P-gp interaction caution."]','A','DOACs: Dabigatran → Direct thrombin; Xa inhibitors (Rivaroxaban, Apixaban, Edoxaban) → factor Xa. Dabigatran reversal = iDArucizumab. Xa reversal = Andexanet Alfa (andeXanet).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','medium','flashcard','Heparin-induced thrombocytopenia (HIT): pathophysiology and management','["HIT type 2 (immune-mediated, clinically important): IgG antibodies form against the heparin-platelet factor 4 (PF4) complex. These antibodies ACTIVATE platelets (paradoxical thrombosis) and reduce platelet count. Timing: platelet fall 5-10 days after first heparin exposure (or within 24h if previous recent exposure). Clinical: thrombocytopenia + paradoxical thrombosis (venous >> arterial). 4T score helps assess probability. Management: (1) STOP all heparin immediately (including LMWH, heparin flushes, heparin-coated catheters). (2) Start non-heparin anticoagulant: argatroban (direct thrombin inhibitor, hepatically cleared — preferred in renal impairment), bivalirudin, or fondaparinux. (3) Do NOT give warfarin alone during acute HIT (can cause venous limb gangrene via protein C depletion)."]','A','HIT = STOP heparin (ALL forms), START argatroban (or bivalirudin). No LMWH (cross-reactive). No warfarin alone acutely. HIT causes CLOTS not just low platelets — the opposite of expected.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','hard','flashcard','Warfarin drug interactions: CYP2C9 inhibitors vs inducers','["Warfarin is primarily metabolized by CYP2C9. Interactions affect INR: CYP2C9 INHIBITORS (raise INR → increased bleeding risk): fluconazole, amiodarone, metronidazole, trimethoprim-sulfamethoxazole, some NSAIDs, omeprazole. CYP2C9/3A4 INDUCERS (lower INR → increased clotting risk): rifampicin (most potent), carbamazepine, phenytoin, phenobarbital, St. John''''s Wort. Pharmacodynamic interactions: vitamin K-containing foods (green leafy vegetables) lower INR; broad-spectrum antibiotics reduce gut flora (decrease vitamin K production → raise INR). Warfarin + aspirin/NSAIDs: increased bleeding risk (pharmacodynamic). Statins may mildly raise INR (CYP2C9 competition)."]','A','INR UP (bleeding risk) = inhibitors of CYP2C9: Fluconazole, Amiodarone, Metronidazole, TMP-SMX. INR DOWN (clot risk) = inducers: Rifampicin, Carbamazepine, Phenytoin, St. John''''s Wort. FARM = inducers of CYP enzymes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','hard','flashcard','Anticoagulation in special populations: pregnancy, renal failure, elderly','["Pregnancy: LMWH or UFH only (does not cross placenta). Warfarin = teratogenic (warfarin embryopathy: weeks 6-12) + fetal hemorrhage. DOACs: unknown fetal safety, not recommended. Renal failure: (1) Dabigatran: 80% renal — avoid CrCl <30 mL/min. (2) Rivaroxaban: ~35% renal — reduce dose in CrCl 15-50 mL/min. (3) Apixaban: ~27% renal — most kidney-safe DOAC; dose reduce if 2 of 3: age ≥80, weight ≤60 kg, Cr ≥1.5 mg/dL. (4) Edoxaban: ~50% renal. Warfarin: hepatically metabolized — relatively safe in renal failure but erratic response. LMWH in CKD: dose reduce or switch to UFH (LMWH renally cleared). Elderly: increased bleeding risk with all agents; use lowest effective dose."]','A','Pregnancy: LMWH/UFH only. Renal failure: Apixaban is safest DOAC (least renal). Dabigatran is most renally dependent — AVOID in CrCl <30. Always check renal function before starting any DOAC.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','easy','flashcard','Fondaparinux: mechanism and distinguishing features','["Fondaparinux is a synthetic pentasaccharide that mimics the minimal ATIII-binding sequence of heparin. It binds ATIII and selectively inhibits factor Xa only (unlike UFH which inhibits both Xa and thrombin, and LMWH which inhibits Xa >> thrombin). Too short to bridge ATIII to thrombin. Given subcutaneously, once daily. Half-life: 17-21 hours (long). Renal elimination — contraindicated in CrCl <30 mL/min. No reversal agent available (protamine does not work). HIT risk very low (does not bind PF4). Does not cause HIT but still carry a theoretical concern. Uses: DVT/PE treatment and prophylaxis, ACS."]','A','Fondaparinux = Selective factor Xa inhibitor via ATIII. Once-daily SC injection. No HIT risk (does not bind PF4). No reversal agent. Avoid in severe renal failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','hard','flashcard','Direct thrombin inhibitors: argatroban, bivalirudin, dabigatran','["Direct thrombin inhibitors (DTIs) directly bind the catalytic site of thrombin without requiring ATIII. They inhibit both free and clot-bound thrombin (advantage over heparin which cannot inhibit clot-bound thrombin). (1) Argatroban: synthetic, IV, hepatically cleared — preferred in HIT with renal impairment. Affects INR (complicates transition to warfarin). (2) Bivalirudin: IV, direct bivalent thrombin inhibitor (binds both catalytic and exosite 1); mostly renally cleared (80%); used in PCI, HIT patients requiring PCI. Short half-life (~25 min in normal renal function). (3) Dabigatran: oral prodrug (dabigatran etexilate → active dabigatran); 80% renally cleared; reversal: idarucizumab. Used for: non-valvular AF, DVT/PE treatment."]','A','DTIs directly hit thrombin — no ATIII needed. Argatroban = HIT + renal failure (hepatic clearance). Bivalirudin = PCI/HIT (IV). Dabigatran = only oral DTI. Remember: iDArucizumab reverses DAbigatran.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Anticoagulants','medium','flashcard','Perioperative anticoagulation management (bridging therapy)','["For patients on warfarin requiring surgery: (1) Assess thrombotic risk (mechanical valve, AF with high CHADS2 score, recent VTE = high risk). (2) Hold warfarin 5 days before surgery (INR falls to <1.5). (3) High-risk patients: bridge with LMWH or IV heparin (stop 24h before surgery for LMWH; 4-6h for IV heparin). (4) Resume warfarin 12-24h postoperatively when hemostasis is achieved. (5) Bridge again if needed until INR therapeutic. Low-risk patients: no bridging needed. DOACs: shorter half-life — hold 24-48h for minor procedures, 48-96h for major/high-bleeding-risk (longer for dabigatran in renal impairment or major surgery)."]','A','Bridging = covering the anticoagulation GAP when warfarin is held for surgery. HIGH-risk patients need bridging with heparin/LMWH. LOW-risk patients: just hold warfarin and restart it after. DOACs: shorter half-life = shorter hold time.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','easy','flashcard','Aspirin: antiplatelet mechanism and dosing','["Aspirin irreversibly acetylates and inactivates cyclooxygenase-1 (COX-1) at serine 529 in platelets. COX-1 catalyzes the first step in thromboxane A2 (TXA2) synthesis. TXA2 is a potent platelet activator and vasoconstrictor. Since platelets have no nucleus, they cannot synthesize new COX-1 → aspirin''''s effect lasts the platelet''''s entire lifespan (7-10 days). Antiplatelet dosing: 75-100 mg/day (low dose is sufficient — completely saturates platelet COX-1). Note: at higher doses, aspirin also inhibits endothelial COX-2-derived prostacyclin (PGI2 — a platelet inhibitor and vasodilator) which partially counteracts antiplatelet effect. GI bleeding risk increases with dose."]','A','Aspirin: irreversible COX-1 killer. Low dose (75-100 mg) is enough for platelet inhibition. Effect lasts 7-10 days (platelet lifespan). STOP 7-10 days before surgery if needed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','easy','flashcard','P2Y12 ADP receptor antagonists: clopidogrel, ticagrelor, prasugrel — comparison','["All block the P2Y12 ADP receptor on platelets, preventing ADP-mediated activation of GP IIb/IIIa and platelet aggregation. Clopidogrel (thienopyridine): prodrug → requires CYP2C19 for activation (genetic polymorphism and omeprazole reduce efficacy); irreversible; maximum effect in 3-5 days. Prasugrel (thienopyridine): prodrug → activated by CYP3A4/2B6 (not CYP2C19); more potent and faster than clopidogrel; irreversible; contraindicated in prior TIA/stroke and age >75/weight <60 kg. Ticagrelor (cyclopentyl-triazolo-pyrimidine): NOT a prodrug → direct reversible binding; fastest onset (1-3 h); does NOT require CYP2C19; dyspnea is unique adverse effect; high-dose aspirin reduces its efficacy."]','A','TiCAGreLOR = Ticker (heart) drug, reversible, NO prodrug activation needed. Clopidogrel = needs CYP2C19 activation (PPI omeprazole blocks it). PraSUGrel = more powerful but contraindicated in prior TIA/stroke.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','medium','flashcard','GP IIb/IIIa inhibitors: abciximab, eptifibatide, tirofiban','["Glycoprotein IIb/IIIa is the final common mediator of platelet aggregation — fibrinogen binds two GP IIb/IIIa receptors on adjacent platelets creating cross-links. GP IIb/IIIa inhibitors block this final step: (1) Abciximab (ReoPro): chimeric monoclonal antibody Fab fragment; irreversible binding; platelet function recovery: 24-48 h after stopping (platelet redistribution). (2) Eptifibatide (Integrilin): cyclic peptide; competitive, reversible; platelet function recovery: 4-8 hours. (3) Tirofiban (Aggrastat): non-peptide small molecule; competitive, reversible; platelet function recovery: 4-8 hours. All given IV with heparin + aspirin as adjunct to PCI. Bleeding is the main adverse effect. No specific reversal agent (platelet transfusion for abciximab)."]','A','GP IIb/IIIa = the FINAL BOSS of platelet aggregation. Block it = block ALL platelet aggregation pathways. ABciximab = AntiBody (longest acting). Eptifibatide and Tirofiban = short-acting small molecules.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','medium','flashcard','Dual antiplatelet therapy (DAPT): indications and duration','["DAPT = aspirin + P2Y12 inhibitor (clopidogrel, ticagrelor, or prasugrel). Indications: (1) ACS (STEMI or NSTEMI): ticagrelor or prasugrel preferred over clopidogrel; continue for 12 months. (2) Drug-eluting stent (DES) placement: minimum 6-12 months of DAPT (to prevent stent thrombosis). (3) Bare-metal stent: minimum 1 month DAPT. Bleeding risk must be balanced against thrombotic risk when determining duration. Premature discontinuation of DAPT after stent placement → risk of stent thrombosis (potentially fatal MI). Patients requiring surgery: assess whether procedure can be delayed until DAPT course complete; if cannot, continue aspirin and stop P2Y12 inhibitor 5-7 days before (ticagrelor/clopidogrel) or 7-10 days before (prasugrel)."]','A','DAPT in ACS: Aspirin + Ticagrelor or Prasugrel for 12 months. In stable DES: DAPT for 6-12 months minimum. Do NOT stop DAPT early after stent — risk of stent thrombosis = sudden MI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','hard','flashcard','CYP2C19 polymorphism and clopidogrel: clinical implications','["Clopidogrel is a prodrug requiring hepatic CYP2C19 to form its active thiol metabolite. CYP2C19 genetic variants: (1) Poor metabolizers (*2/*2 genotype, common in East Asians 15%, Caucasians 2-3%): significantly reduced active metabolite formation → reduced platelet inhibition → increased risk of stent thrombosis and MACE. (2) Intermediate metabolizers: intermediate response. (3) Rapid/ultra-rapid metabolizers: may have higher active metabolite exposure. Clinical management of poor metabolizers: switch to ticagrelor or prasugrel (not CYP2C19-dependent). Drug interaction: omeprazole/esomeprazole inhibit CYP2C19 → reduce clopidogrel efficacy → use pantoprazole or H2 blocker instead. Point-of-care genetic testing (CYP2C19 genotyping) is available and sometimes performed in high-risk patients."]','A','CYP2C19 = the KEY to clopidogrel. Poor metabolizers get LESS antiplatelet effect. Omeprazole blocks CYP2C19 too. If CYP2C19 poor metabolizer → switch to Ticagrelor (no CYP2C19 needed) or Prasugrel.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','hard','flashcard','Antiplatelet therapy in secondary prevention of stroke and TIA','["After ischemic stroke or TIA: (1) Non-cardioembolic stroke/TIA: aspirin (50-325 mg) OR clopidogrel (75 mg) OR aspirin + extended-release dipyridamole (Aggrenox). Dual clopidogrel + aspirin for 21 days after minor stroke/TIA (POINT/CHANCE trials) then monotherapy. (2) Cardioembolic stroke (AF): anticoagulation (warfarin or DOAC) is preferred over antiplatelet therapy. (3) AF-related stroke while on anticoagulation: improve anticoagulation or address modifiable risk factors, not add antiplatelet. Prasugrel is CONTRAINDICATED in prior TIA/stroke (increased intracranial hemorrhage). Ticlopidine: historically used but now avoided (TTP, agranulocytosis risk)."]','A','Stroke from AF → anticoagulate (not just antiplatelet). Non-cardioembolic stroke → antiplatelet (aspirin, clopidogrel, or aspirin+dipyridamole). Prasugrel is contraindicated in stroke/TIA history.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','easy','flashcard','Dipyridamole: mechanism and clinical use','["Dipyridamole inhibits phosphodiesterase (PDE), preventing breakdown of cAMP and cGMP in platelets. Increased cAMP inhibits platelet activation. Also blocks adenosine uptake by erythrocytes and platelets, increasing extracellular adenosine which further increases cAMP. May also inhibit thromboxane synthase. Used primarily in combination with aspirin (Aggrenox) for secondary prevention of stroke and TIA. Vasodilating properties can cause coronary steal — contraindicated in unstable angina and used as a pharmacologic stressor in myocardial perfusion imaging (dipyridamole stress test). Adverse effects: headache, dizziness, GI upset."]','A','Dipyridamole: PDE inhibitor → more cAMP in platelets → less sticky. Used with ASPIRIN for stroke prevention (Aggrenox). NEVER use alone in unstable angina (causes coronary steal).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','medium','flashcard','Cangrelor: unique features among P2Y12 antagonists','["Cangrelor is the only IV P2Y12 receptor antagonist. It directly and reversibly binds P2Y12 without requiring bioactivation. Onset: maximum platelet inhibition within 2 minutes of IV infusion. Offset: platelet function recovers within 30-60 minutes of stopping (extremely fast reversal due to short half-life of ~3-5 minutes). Uses: adjunct to PCI in patients not pre-treated with a P2Y12 inhibitor or when oral P2Y12 agents cannot be administered. Advantage over GP IIb/IIIa inhibitors: faster and more complete P2Y12-specific inhibition with rapid reversal. Important: oral P2Y12 inhibitors should be started after cangrelor infusion ends (cangrelor blocks the platelet P2Y12 receptor and prevents clopidogrel/prasugrel from binding)."]','A','Cangrelor = the only IV P2Y12 blocker. Works in MINUTES and wears off in 30-60 minutes. Give oral P2Y12 inhibitor AFTER (not during) cangrelor to avoid pharmacodynamic interference.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','hard','flashcard','Bleeding risk with antiplatelets: management and reversal','["Aspirin-induced bleeding: no specific antidote. Platelet transfusion can restore COX-1 function (if >10 days since last dose, new platelets have functional COX-1). For life-threatening bleeding on DAPT: (1) Transfuse platelets (aspirin-inhibited platelets diluted by new ones; clopidogrel/prasugrel: wait at least 5 h after last dose before transfusing since active metabolite clears — reduces antagonism of transfused platelets). (2) DDAVP (desmopressin): releases vWF from endothelium, may improve hemostasis. (3) Aminocaproic acid or tranexamic acid (antifibrinolytics). GP IIb/IIIa inhibitors: no antidote; platelet transfusion may help for abciximab (redistribution); eptifibatide/tirofiban: stop infusion and allow clearance (4-8 h)."]','A','Antiplatelet reversal: platelet transfusion is primary strategy. Aspirin: new platelets from donor have intact COX-1. Clopidogrel: wait 5 hours after last dose (active metabolite clears). DDAVP can also help in emergencies.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Antiplatelets','hard','flashcard','Antiplatelet therapy in ACS: evidence and drug selection','["Post-ACS antiplatelet strategy: (1) All ACS patients receive aspirin (325 mg loading, then 75-100 mg daily indefinitely). (2) Add P2Y12 inhibitor for 12 months: ticagrelor or prasugrel preferred over clopidogrel (stronger inhibition, better outcomes in PLATO and TRITON-TIMI 38 trials). (3) Prasugrel not used in: prior TIA/stroke, age >75, weight <60 kg, or medical management without PCI. (4) GP IIb/IIIa inhibitors: reserved for high-risk PCI (large thrombus burden, no pre-treatment with oral P2Y12 inhibitor). Ticagrelor is used even without PCI (PLATO trial showed benefit in medically managed ACS). After 12 months in stable patients: consider dropping to aspirin monotherapy or ticagrelor monotherapy."]','A','ACS = Aspirin + Ticagrelor (preferred) or Prasugrel for 12 months. Clopidogrel if ticagrelor/prasugrel contraindicated. GP IIb/IIIa = adjunct at PCI only (reserved use). PLATO = Ticagrelor beats Clopidogrel.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','easy','flashcard','Fibrinolytic system: physiology and thrombolytic drug mechanism','["Endogenous fibrinolysis: tissue plasminogen activator (tPA) is released by endothelial cells and converts plasminogen → plasmin. Plasmin degrades fibrin clots and fibrinogen. Thrombolytic drugs mimic or enhance this process: (1) tPA variants (alteplase, tenecteplase, reteplase): fibrin-specific — form ternary complex with fibrin + plasminogen → activate plasminogen locally at the clot. (2) Streptokinase: non-fibrin-specific — forms complex with circulating plasminogen systemically → systemic lytic state (degrades fibrinogen, factors V, VIII). Net effect: clot dissolution restoring vessel patency. Alpha-2-antiplasmin is the endogenous inhibitor of plasmin — thrombolytics overcome this."]','A','Thrombolytics: activate PLASMINOGEN → PLASMIN → chews up FIBRIN. tPA = fibrin-specific (clot-targeted). Streptokinase = systemic (destroys everything). Alpha-2-antiplasmin = natural brake on fibrinolysis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','easy','flashcard','Alteplase vs tenecteplase vs streptokinase: comparison','["Alteplase (tPA): recombinant tPA; fibrin-specific; given as weight-based bolus + infusion over 60-90 minutes; half-life ~5 min; used in STEMI, acute ischemic stroke (AIS), massive PE. Tenecteplase (TNK-tPA): genetically modified tPA — longer half-life (~20 min), higher fibrin specificity, resistant to PAI-1; single weight-based IV bolus (most convenient for STEMI). Reteplase: longer half-life than alteplase; given as two IV boluses 30 min apart. Streptokinase: derived from Group C streptococci; non-fibrin-specific, antigenic (neutralizing antibodies, avoid re-use); cheapest; given by infusion; can cause hypotension and anaphylaxis; rarely used now."]','A','Single bolus thrombolytics: Tenecteplase (TNK). Two bolus: Reteplase. Long infusion: Alteplase. Streptokinase = cheapest, most antigenic, least fibrin-specific (systemic lysis).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','medium','flashcard','Thrombolytics in STEMI: indications and time windows','["Thrombolysis in STEMI is indicated when: (1) Primary PCI is not available within 120 minutes of first medical contact, AND (2) Symptom onset <12 hours (greatest benefit within 3 hours). Benefits: reduces infarct size, restores patency in 50-85% of cases. Preferred agent: tenecteplase (single bolus, easy administration). After thrombolysis: anticoagulation with enoxaparin or UFH for 48 hours. Transfer for PCI (pharmaco-invasive strategy) if: failed thrombolysis (PCI within 3-24 hours), successful thrombolysis (elective PCI within 3-24 hours). Failed thrombolysis: defined as <50% ST resolution at 60-90 minutes → rescue PCI."]','A','Thrombolysis in STEMI: give when PCI is >120 min away. Best in <3 hours. Single bolus TNK is easiest. After thrombolysis: check ST resolution at 60-90 min. <50% resolution → rescue PCI immediately.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','medium','flashcard','Thrombolytics in acute ischemic stroke: protocol and contraindications','["IV alteplase 0.9 mg/kg (max 90 mg) — 10% as IV bolus, then 90% infusion over 60 minutes. Time window: within 4.5 hours of symptom onset. Absolute contraindications: (1) Prior intracranial hemorrhage, (2) Current intracranial neoplasm, (3) Active internal bleeding, (4) Significant head trauma or stroke within 3 months, (5) BP > 185/110 mmHg (must be controlled first), (6) Ischemic stroke within 3 months, (7) Infective endocarditis. Relative contraindications: INR > 1.7, platelets < 100,000, current anticoagulant use. Before giving: CT head (exclude hemorrhagic stroke), blood glucose (hypoglycemia mimics stroke). Do not give aspirin or anticoagulants for 24 h after alteplase."]','A','IV tPA in stroke: 0.9 mg/kg within 4.5 hours. CT first to exclude hemorrhage. BP must be <185/110 before giving. DO NOT give aspirin or anticoagulants for 24h after tPA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','medium','flashcard','Thrombolytics in massive pulmonary embolism','["Massive PE: defined as PE causing hemodynamic instability (systolic BP < 90 mmHg for >15 min, or requiring vasopressors, or cardiac arrest). In massive PE: systemic thrombolysis with alteplase (100 mg IV over 2 hours) is indicated if no absolute contraindications. Benefits: rapid dissolution of thrombus, rapid reduction in right heart strain, immediate hemodynamic improvement. After thrombolysis: switch to anticoagulation (heparin). Submassive PE (right heart strain + elevated troponin/BNP but hemodynamically stable): controversial — anticoagulation alone is standard; thrombolysis considered in deteriorating patients. Surgical embolectomy or catheter-directed thrombolysis: alternatives when systemic thrombolysis contraindicated."]','A','Massive PE = hemodynamic instability → Thrombolyse immediately (alteplase 100 mg over 2h). Submassive PE = stable but stressed RV → anticoagulate, monitor, and only thrombolyse if deteriorating.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','hard','flashcard','Absolute and relative contraindications to thrombolytic therapy','["Absolute contraindications (any active or recent): (1) Prior intracranial hemorrhage at any time, (2) Ischemic stroke within 3 months, (3) Intracranial neoplasm, AVM, or aneurysm, (4) Active internal bleeding (not menses), (5) Suspected aortic dissection, (6) Significant closed-head or facial trauma within 3 months. Relative contraindications: (1) Severe uncontrolled hypertension (BP > 180/110), (2) History of chronic severe hypertension, (3) Traumatic or prolonged CPR, (4) Major surgery within 3 weeks, (5) Internal bleeding within 2-4 weeks, (6) Non-compressible vascular punctures, (7) Pregnancy, (8) Active peptic ulcer, (9) Warfarin use with INR > 1.7."]','A','Absolute: PRIOR intracranial hemorrhage (any time), ACTIVE bleeding, SUSPECTED aortic dissection, INTRACRANIAL neoplasm/AVM, RECENT stroke/head trauma. Remember: aortic dissection is absolute — thrombolysis lyses the protective clot and causes fatal rupture.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','hard','flashcard','Complications of thrombolytic therapy: management','["Major complication: hemorrhage (especially intracranial hemorrhage — ICH). ICH occurs in 0.5-1% of STEMI patients; 6% in ischemic stroke patients. Risk factors for ICH: age > 65, low body weight, uncontrolled hypertension, prior stroke, excessive anticoagulation. Management of life-threatening bleeding after thrombolysis: (1) Stop thrombolytic infusion, (2) Cryoprecipitate (replaces fibrinogen — give 10 units), (3) Fresh frozen plasma (replaces clotting factors), (4) Platelet transfusion (if thrombocytopenic or severe bleeding), (5) Antifibrinolytics: aminocaproic acid or tranexamic acid (inhibit plasminogen activation — counter fibrinolytic effect), (6) Urgent neurosurgical consultation for ICH. There is no specific antidote."]','A','Thrombolytic hemorrhage: CRYOPRECIPITATE (replaces fibrinogen) + FFP + antifibrinolytics (aminocaproic acid or tranexamic acid). No specific antidote — must replenish what was destroyed.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','easy','flashcard','Streptokinase: mechanism of action and antigenicity','["Streptokinase is a non-enzymatic protein from beta-hemolytic streptococci. It is NOT a plasminogen activator itself — instead it forms a 1:1 complex with plasminogen (or plasmin), which then acquires enzymatic activity and converts free plasminogen to plasmin systemically. This systemic lytic state degrades fibrinogen, factors V and VIII, and fibrin indiscriminately. Antigenicity: prior streptococcal infection or prior streptokinase use generates neutralizing IgG antibodies — subsequent use may be ineffective or cause anaphylaxis. Avoid re-use within 12 months. Also causes hypotension (bradykinin release). Cheapest thrombolytic."]','A','Streptokinase makes a COMPLEX with plasminogen → becomes active. NOT fibrin-specific — causes systemic lysis. ANTIGENIC — prior strep infection or prior use → antibodies. Avoid re-use within 12 months.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','hard','flashcard','Thrombolytics vs anticoagulants: key conceptual difference','["Anticoagulants (heparin, warfarin, DOACs): PREVENT new clot formation — they inhibit coagulation factors in the clotting cascade. They do NOT dissolve existing clots. Thrombolytics (alteplase, streptokinase): DISSOLVE existing clots by activating plasminogen → plasmin → fibrinolysis. They do NOT prevent new clot formation (hence anticoagulants are typically used concomitantly or after thrombolysis). Combined use: thrombolytics are given first to dissolve the acute clot; then anticoagulants are started (after thrombolytic infusion complete) to maintain patency and prevent recurrence. Clinical pearl: heparin must be started after thrombolysis in STEMI to maintain coronary artery patency."]','A','Thrombolytics = dissolve existing clot (retrospective action). Anticoagulants = prevent new clot (prospective action). Use BOTH: thrombolytics to open the vessel, then anticoagulants to keep it open.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Thrombolytics','medium','flashcard','Pharmacokinetics of thrombolytics','["Alteplase: IV administration, half-life ~5 minutes (cleared rapidly by liver), given as bolus + infusion (e.g., 60-minute infusion for STEMI, 3-hour for PE, 60-minute for stroke with 10% bolus first). Tenecteplase: half-life ~20-25 minutes due to longer T½ from modified glycosylation; single bolus; more fibrin-specific, resistant to plasminogen activator inhibitor-1 (PAI-1). Reteplase: half-life ~15 minutes; two IV boluses 30 minutes apart. Streptokinase: half-life ~20-80 minutes; given by infusion over 30-60 minutes. None are oral (proteins subject to GI degradation); all IV. Drug interactions: anticoagulants and antiplatelets given concurrently increase bleeding risk."]','A','Alteplase = shortest half-life (~5 min) → needs infusion. Tenecteplase = 20 min → single bolus (fastest to administer). Streptokinase = longest infusion but cheapest. All are IV proteins.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','easy','flashcard','Pathophysiology of PAH and treatment targets','["Pulmonary arterial hypertension (PAH) is characterized by: (1) pulmonary vasoconstriction, (2) vascular remodeling and smooth muscle proliferation, (3) right ventricular pressure overload and eventual failure. Three key pathogenic pathways, each a therapeutic target: (1) Nitric oxide (NO) pathway: NO deficiency → decreased cGMP → vasoconstriction. Targets: PDE-5 inhibitors (sildenafil, tadalafil), soluble guanylyl cyclase stimulators (riociguat). (2) Endothelin pathway: ET-1 excess → vasoconstriction + proliferation. Targets: endothelin receptor antagonists (bosentan, ambrisentan, macitentan). (3) Prostacyclin pathway: prostacyclin deficiency → platelet activation + vasoconstriction. Targets: prostacyclin analogues (epoprostenol, treprostinil, iloprost, selexipag)."]','A','3 PAH pathways: (1) NO↓ → PDE-5 inhibitors, riociguat. (2) ET-1↑ → endothelin antagonists. (3) Prostacyclin↓ → prostacyclin analogues. Combination therapy targeting multiple pathways improves outcomes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','easy','flashcard','PDE-5 inhibitors in PAH: sildenafil and tadalafil','["Sildenafil and tadalafil inhibit phosphodiesterase type 5 (PDE-5), which degrades cGMP in pulmonary vascular smooth muscle. PDE-5 inhibition → increased cGMP → activation of protein kinase G → vascular smooth muscle relaxation and vasodilation of the pulmonary vasculature → decreased pulmonary vascular resistance and right heart afterload. Sildenafil (Revatio): 20 mg TID for PAH (different from erectile dysfunction dosing 25-100 mg). Tadalafil (Adcirca): 40 mg once daily for PAH (different from Cialis 2.5-20 mg). ABSOLUTE contraindication: nitrates (co-administration causes severe hypotension via additive cGMP elevation). Also contraindicated with riociguat."]','A','PDE-5 inhibitors in PAH → increase cGMP → relax pulmonary arteries. Sildenafil (TID) vs Tadalafil (once daily — longer half-life). NEVER combine with nitrates or riociguat (additive hypotension).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','medium','flashcard','Endothelin receptor antagonists: bosentan, ambrisentan, macitentan','["Endothelin-1 (ET-1) binds ET-A receptors (vasoconstriction, proliferation) and ET-B receptors on smooth muscle (vasoconstriction) and endothelium (ET-B on endothelium releases NO/prostacyclin — vasodilatory). Bosentan: dual ET-A and ET-B antagonist; CYP3A4 and CYP2C9 inducer (reduces efficacy of many drugs including hormonal contraceptives, statins); hepatotoxic (monthly LFTs mandatory); teratogenic (Category X). Ambrisentan: selective ET-A antagonist; less hepatotoxicity than bosentan; once daily. Macitentan: dual ET-A and ET-B antagonist; better tissue penetration, longer half-life, once daily; used in combination therapy (SERAPHIN trial). All: teratogenic — mandatory contraception for women of childbearing potential."]','A','All ERA drugs: TERATOGENIC + monthly LFTs. Bosentan: induces CYP3A4 (watch drug interactions). Ambrisentan: ET-A selective (less hepatotoxic). Macitentan: better tissue penetration, once daily.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','medium','flashcard','Prostacyclin analogues in PAH: epoprostenol, iloprost, treprostinil','["Prostacyclin (PGI2) analogs activate IP (prostacyclin) receptors on pulmonary vascular smooth muscle → increased cAMP → vasodilation and antiproliferation. Also inhibit platelet aggregation. Routes of administration: (1) Epoprostenol (Flolan): IV only (central line required, continuous infusion, half-life 3-5 min); most potent; rebound fatal PAH if abruptly discontinued. (2) Iloprost (Ventavis): inhaled (6-9 inhalations/day); selectively targets pulmonary vasculature; t½ 20-30 min. (3) Treprostinil (Remodulin): IV or SC continuous infusion (SC causes site pain) or inhaled; longer t½. (4) Selexipag (Uptravi): oral selective IP receptor agonist (not a prostacyclin analog per se but same receptor). Adverse effects: flushing, jaw pain, diarrhea, nausea."]','A','Prostacyclin analogs: Epoprostenol = most potent, IV only, short half-life (never interrupt). Iloprost = inhaled (lungs directly). Treprostinil = IV or SC or inhaled. Selexipag = only oral IP receptor agonist.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','medium','flashcard','Riociguat: mechanism and indications beyond PAH','["Riociguat (Adempas) is a soluble guanylyl cyclase (sGC) stimulator. It has a dual mechanism: (1) Sensitizes sGC to endogenous NO (increasing cGMP even with low NO levels), and (2) Directly stimulates sGC independently of NO. Result: increased cGMP → pulmonary vasodilation and antiproliferative effects. Approved indications: (1) PAH (Group 1), (2) Chronic thromboembolic pulmonary hypertension (CTEPH, Group 4) — ONLY drug approved specifically for CTEPH inoperable or persistent after surgery. Contraindications: PDE-5 inhibitors (severe additive hypotension via excess cGMP), nitrates, pregnancy (teratogenic). Note: unlike sildenafil, riociguat also works without NO present."]','A','Riociguat: stimulates sGC directly AND sensitizes to NO → more cGMP → pulmonary vasodilation. UNIQUE: only drug approved for CTEPH. Absolute contraindication: PDE-5 inhibitors + nitrates.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','hard','flashcard','Combination therapy in PAH: current evidence','["Modern PAH management uses combination therapy targeting multiple pathways: (1) AMBITION trial: upfront combination of ambrisentan (ERA) + tadalafil (PDE-5i) was superior to monotherapy in treatment-naive PAH patients (reduced clinical failure by 50%). (2) GRIPHON trial: adding selexipag (IP receptor agonist) to background ERA + PDE-5i reduced morbidity/mortality. (3) SERAPHIN trial: macitentan (ERA) + background therapy reduced morbidity/mortality. Risk stratification guides therapy intensity: low risk → oral combination; intermediate → add inhaled/SC prostacyclin; high risk (rapidly progressive, RV failure) → IV epoprostenol (gold standard for severe PAH). Triple oral combination (ERA + PDE-5i + selexipag) increasingly used."]','A','PAH combo therapy: ERA + PDE-5i is the preferred initial combination. Add IP agonist for deteriorating patients. IV epoprostenol = gold standard for high-risk/severe PAH. Never delay treatment — PAH is progressive and fatal without treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','hard','flashcard','Acute vasodilator testing in PAH: rationale and significance','["Acute vasodilator testing (AVT) is performed in the catheterization lab in newly diagnosed PAH patients using a short-acting vasodilator (inhaled NO, IV epoprostenol, or adenosine). Purpose: identify patients with vasoreactive PAH (a subset with preserved vascular reactivity) — these patients have dramatic improvement with calcium channel blockers (high-dose amlodipine, diltiazem, nifedipine). A positive response: mean PAP reduction ≥10 mmHg to ≤40 mmHg with maintained/increased CO. Only ~10-15% of PAH patients are vasoreactive. Vasoreactive patients who respond to CCBs have significantly better prognosis. Non-responders should receive PAH-specific therapy (ERA, PDE-5i, prostacyclins) — CCBs are HARMFUL in non-vasoreactive PAH (can worsen RV function)."]','A','Vasoreactivity testing in PAH: 10-15% of patients are ''''responders'''' → respond to high-dose CCBs (amlodipine/diltiazem). Test with inhaled NO or IV epoprostenol. Non-responders: CCBs are DANGEROUS — use PAH-specific drugs instead.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','easy','flashcard','Monitoring and supportive therapy in PAH','["PAH management also includes: (1) Anticoagulation: warfarin (INR 1.5-2.5) is used in some PAH guidelines (increased risk of in situ pulmonary artery thrombosis and RV thrombus); unclear benefit in non-idiopathic PAH. (2) Diuretics: reduce volume overload and right ventricular preload (loop diuretics, spironolactone). (3) Oxygen: supplemental O2 if SpO2 <91% (hypoxia worsens pulmonary vasoconstriction). (4) Exercise and rehabilitation: improves functional capacity in stable PAH. (5) Monitoring: 6-minute walk test, BNP/NT-proBNP, echocardiography (right heart function), right heart catheterization. (6) Avoid pregnancy (extremely high mortality in PAH). (7) Avoid NSAIDs (worsen renal function and cause sodium retention)."]','A','PAH supportive care: O2 for hypoxia, loop diuretics for RV volume overload, anticoagulation (in idiopathic PAH), exercise rehabilitation. Pregnancy is EXTREMELY dangerous in PAH — must advise contraception.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','hard','flashcard','CTEPH: pathophysiology and treatment differences from PAH','["Chronic thromboembolic pulmonary hypertension (CTEPH, Group 4 PH) is caused by organized chronic thrombi obstructing pulmonary arteries after PE — not resolved by anticoagulation. This is distinct from PAH (Group 1). Treatment: (1) Anticoagulation: lifelong for all CTEPH patients (prevents new VTE, not the CTEPH per se). (2) Pulmonary endarterectomy (PEA): surgical removal of organized thromboembolic material — potentially curative if accessible lesions; performed at specialized centers. (3) Balloon pulmonary angioplasty (BPA): for inoperable CTEPH. (4) Riociguat: only PAH-specific drug approved for inoperable CTEPH or persistent/recurrent CTEPH after PEA (CHEST-1 trial). ERA and PDE-5i: used off-label but not specifically approved for CTEPH."]','A','CTEPH ≠ PAH. CTEPH is caused by UNRESOLVED CLOTS. Primary treatment: surgery (PEA) = potentially curative. If inoperable → riociguat (only drug specifically approved) + BPA. Anticoagulate ALL CTEPH patients for life.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drugs for Pulmonary Hypertension','medium','flashcard','Classification of pulmonary hypertension (WHO groups) and drug applicability','["WHO Groups: (1) PAH: idiopathic, heritable, drug/toxin-induced (e.g., anorexigens, dasatinib, methamphetamine), associated with connective tissue disease, HIV, portal hypertension, congenital heart disease. Drugs approved here: PDE-5i, ERAs, prostacyclins, riociguat. (2) PH due to left heart disease: most common cause — treat underlying heart disease; PAH-specific drugs generally NOT indicated (may worsen LH disease by increasing venous return). (3) PH due to lung disease/hypoxia: treat underlying lung disease + oxygen; PAH drugs not approved. (4) CTEPH: riociguat + PEA/BPA. (5) Unclear/multifactorial: treat underlying cause. Key point: PAH-specific medications are ONLY approved for Group 1 and Group 4 — using them in Groups 2-3 is potentially harmful."]','A','Only Group 1 (PAH) and Group 4 (CTEPH, riociguat) have specific drug therapies. Groups 2, 3, 5: treat the CAUSE — do not use PAH drugs. Wrong diagnosis → wrong drug → potentially fatal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','easy','flashcard','Key cardiovascular drug interactions with warfarin','["Warfarin (CYP2C9 substrate) interactions: INCREASE INR (bleeding risk — CYP2C9 inhibitors): amiodarone (most potent), fluconazole, metronidazole, trimethoprim-sulfamethoxazole, fluoroquinolones, some statins. DECREASE INR (clot risk — CYP2C9 inducers): rifampicin, carbamazepine, phenytoin, St. John''''s Wort. PHARMACODYNAMIC interactions (increase bleeding regardless of INR): NSAIDs (inhibit platelet COX-1), aspirin, P2Y12 inhibitors. Dietary: green leafy vegetables high in vitamin K (spinach, kale) lower INR. Broad-spectrum antibiotics: reduce gut bacteria that produce vitamin K → raise INR. Important: check INR more frequently when starting any new drug in a warfarin patient."]','A','Warfarin rule: check INR with ANY new drug. Amiodarone + Warfarin = dangerous INR rise. Rifampicin + Warfarin = dangerous INR drop. Green leafy vegetables = lower INR (vitamin K content).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','easy','flashcard','Digoxin drug interactions: amiodarone, verapamil, and renal factors','["Digoxin has a narrow therapeutic index (target 0.5-0.9 ng/mL). Drug interactions that INCREASE digoxin levels (toxicity risk): (1) Amiodarone: inhibits P-glycoprotein and renal elimination → reduce digoxin dose by 50%. (2) Verapamil: inhibits P-glycoprotein and reduces renal digoxin secretion → reduce digoxin dose by 50%. (3) Quinidine: inhibits P-glycoprotein → doubles digoxin levels. (4) Clarithromycin, itraconazole: inhibit P-gp. Conditions increasing toxicity risk: renal failure (digoxin 75% renally cleared), hypokalemia (reduced competition at Na/K-ATPase), hypomagnesemia, hypercalcemia, hypothyroidism (decreased renal clearance)."]','A','Digoxin toxicity triggers: AMIODARONE + VERAPAMIL + QUINIDINE (P-gp inhibitors → reduce digoxin dose 50%). Low K+ = MORE toxic. Renal failure = accumulation. Watch all three together.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','medium','flashcard','Statin drug interactions: CYP3A4 inhibitors and fibrates','["CYP3A4 inhibitors increase simvastatin/atorvastatin/lovastatin levels → rhabdomyolysis risk: (1) Azole antifungals (itraconazole, ketoconazole — avoid combination with simvastatin/lovastatin). (2) Macrolide antibiotics (clarithromycin, erythromycin — hold statin during short course). (3) HIV protease inhibitors (ritonavir, atazanavir). (4) Grapefruit juice (intestinal CYP3A4 inhibitor — avoid with simvastatin/lovastatin). (5) Cyclosporine (also inhibits OATP1B1). Fibrate interaction: gemfibrozil inhibits OATP1B1 (reduces hepatic statin uptake) + UGT (reduces glucuronidation) → simvastatin contraindicated with gemfibrozil; fenofibrate is safer. Pravastatin and rosuvastatin are safest (minimal CYP3A4)."]','A','STOP Statin when giving Clarithromycin (macrolide). Grapefruit = CYP3A4 inhibitor in gut — avoid with simvastatin. Safest statins with drug interactions: PRAvastatin (no CYP) and ROSUvastatin (CYP2C9 only).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','medium','flashcard','Beta-blocker + verapamil/diltiazem: dangerous combination','["Both non-dihydropyridine CCBs (verapamil, diltiazem) and beta-blockers independently: (1) Slow SA node automaticity, (2) Prolong AV nodal conduction, (3) Reduce cardiac contractility. Combined use: additive/synergistic depression of SA node, AV node, and ventricular function → risk of severe bradycardia, high-degree AV block, and asystole. This combination is particularly dangerous in patients with pre-existing AV nodal disease, sick sinus syndrome, or reduced LV function. IV verapamil after IV beta-blocker = especially dangerous (can cause sudden cardiac arrest). Oral combination may be used cautiously in selected patients (rate control in AF with close monitoring) — only under specialist supervision."]','A','Verapamil/Diltiazem + Beta-blocker = additive AV nodal depression. Risk: bradycardia → AV block → asystole. NEVER give IV verapamil after IV beta-blocker (cardiac arrest risk). Monitor closely if used together.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','medium','flashcard','NSAIDs in cardiovascular patients: adverse interactions','["NSAIDs (ibuprofen, naproxen, diclofenac) inhibit cyclooxygenase (COX-1 and COX-2) reducing prostaglandin E2 (PGE2) and prostacyclin (PGI2) in the kidney. Renal prostaglandins normally vasodilate afferent arterioles (maintain GFR) and promote natriuresis. NSAIDs reduce these effects → sodium and water retention → (1) Hypertension (counteract antihypertensive drug effect), (2) HF exacerbation (increase preload/afterload), (3) AKI (reduce renal perfusion especially with ACE inhibitors, diuretics, or existing CKD). NSAIDs also interact with anticoagulants pharmacodynamically: increase GI bleeding risk with anticoagulants; may slightly increase warfarin levels (CYP2C9 competition). Non-selective NSAIDs (especially diclofenac, COX-2 selective inhibitors like celecoxib) increase cardiovascular risk (MI, stroke) due to loss of prostacyclin with preserved TXA2 effect."]','A','NSAIDs are the ENEMY of cardiovascular patients: raise BP, worsen HF, worsen kidneys, increase GI bleeding. Avoid in HF, CKD, patients on anticoagulants. Acetaminophen is preferred for pain in CV patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','hard','flashcard','Serotonin syndrome vs NMS: key differences relevant to cardiovascular drugs','["Serotonin syndrome can involve cardiovascular drugs: MAO inhibitors (phenelzine), linezolid (inhibits MAO), meperidine, tramadol + serotonergic drugs. Cardiovascular effects: tachycardia, hypertension, hyperthermia, diaphoresis, tremor/clonus. CV drugs involved: some antidepressants (SSRIs, SNRIs), dextromethorphan, fentanyl (weak serotonergic). Treatment: cyproheptadine (5-HT2 antagonist), supportive care, stop offending agents. Neuroleptic malignant syndrome (NMS): caused by dopamine antagonists (antipsychotics); muscle rigidity (''''lead-pipe''''), hyperthermia, autonomic instability; treat with bromocriptine (dopamine agonist) and dantrolene (muscle relaxant). QT prolongation: many cardiovascular drugs (sotalol, quinidine, amiodarone) + non-cardiac drugs (antipsychotics, macrolides, fluoroquinolones) can cause additive QT prolongation → torsades de pointes."]','A','QT prolongation: antiarrhythmics (class IA, III) + antipsychotics + macrolides + fluoroquinolones = additive risk. Always check QT before adding a QT-prolonging drug. Azithromycin + sotalol = dangerous combination.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','hard','flashcard','CYP450-mediated drug interactions in cardiology: clinical relevance','["Key cardiovascular CYP450 interactions: (1) CYP2C19: clopidogrel activation (omeprazole inhibits → reduces efficacy). (2) CYP2C9: warfarin metabolism (fluconazole, amiodarone inhibit → raise INR; rifampicin induces → lowers INR). (3) CYP3A4: statins (clarithromycin, azole antifungals inhibit → rhabdomyolysis); CCBs (grapefruit juice inhibits → increased levels). (4) CYP2D6: metoprolol, carvedilol (fluoxetine, paroxetine inhibit → bradycardia); codeine activation. (5) P-glycoprotein (P-gp): digoxin transport (amiodarone, verapamil, quinidine inhibit → digoxin toxicity); dabigatran transport. Important: amiodarone inhibits CYP1A2, CYP2C9, CYP2D6, CYP3A4, and P-gp — interacts with almost every cardiovascular drug."]','A','Amiodarone = MASTER INHIBITOR: inhibits CYP1A2, 2C9, 2D6, 3A4, AND P-gp. Starting amiodarone = reduce digoxin by 50%, reduce warfarin by 30-50%, monitor for beta-blocker bradycardia. The most drug-interactive cardiovascular drug.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','easy','flashcard','Adverse effects of ACE inhibitors: complete profile','["ACE inhibitor adverse effects: (1) DRY COUGH (most common — 10-15%): bradykinin accumulation in airways; class effect; switch to ARB. (2) ANGIOEDEMA (rare but life-threatening): bradykinin-mediated swelling of face, lips, tongue, larynx; more common in African-Americans; STOP immediately; treat with epinephrine/corticosteroids/antihistamines; airway protection. (3) HYPERKALEMIA: reduced aldosterone → K+ retention; worse with K+-sparing diuretics or K+ supplements. (4) HYPOTENSION: first-dose effect especially in volume-depleted patients; start low in HF/CKD. (5) ACUTE KIDNEY INJURY: especially in bilateral RAS, volume depletion, NSAIDs; monitor creatinine. (6) TERATOGENICITY (Category D): fetal renal dysplasia, oligohydramnios; STOP in pregnancy. Contraindicated: bilateral RAS, pregnancy, history of angioedema from ACE inhibitor."]','A','ACE inhibitor adverse effects: CAPTOPRIL: Cough, Angioedema (life-threatening), Proteinuria (reduced — actually protective), Taste disturbance, Orthostatic hypotension, Potassium rise (hyperkalemia), Renal impairment, Impaired fetal development (teratogenic).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','hard','flashcard','Adverse effects of antiarrhythmics: comparison across classes','["Class IA (quinidine, procainamide, disopyramide): QT prolongation → torsades de pointes; quinidine: cinchonism (tinnitus, blurred vision, headache); procainamide: lupus-like syndrome; disopyramide: most anticholinergic. Class IB (lidocaine): CNS toxicity (nystagmus, seizures), only with IV use. Class IC (flecainide, propafenone): proarrhythmic in structural heart disease (CAST trial); propafenone: bronchospasm (beta-blocking). Class II (beta-blockers): bradycardia, bronchospasm (non-selective), fatigue, sexual dysfunction, mask hypoglycemia symptoms. Class III (amiodarone): pulmonary toxicity, hepatotoxicity, thyroid dysfunction (hypo or hyperthyroid), corneal deposits, photosensitivity, peripheral neuropathy. Sotalol: QT prolongation → TdP; bronchospasm. Class IV (verapamil, diltiazem): bradycardia, AV block, negative inotropy (HF), constipation (verapamil)."]','A','AMIODARONE side effects: PLATES (Pulmonary, Liver, Abnormal thyroid, corneal deposiTs, Electro-photosensitivity, Skin discoloration). Quinidine = cinchonism. Procainamide = lupus. Disopyramide = dry mouth/retention (anticholinergic).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Cardiovascular System','Pharmacology','Drug Interactions and Adverse Effects','medium','flashcard','Adverse effects of commonly used cardiovascular drugs: quick reference','["Thiazides: hypokalemia, hyponatremia, hyperuricemia, hyperglycemia, hypercalcemia. Loop diuretics: hypokalemia, hyponatremia, ototoxicity (at high IV doses), hypocalcemia, metabolic alkalosis. Spironolactone: hyperkalemia, gynecomastia, menstrual irregularities. ACE inhibitors: cough, angioedema, hyperkalemia. ARBs: hyperkalemia, teratogenic (no cough/angioedema). Beta-blockers: bradycardia, fatigue, bronchospasm (non-selective), sexual dysfunction, mask hypoglycemia, abrupt withdrawal (rebound hypertension). CCBs: amlodipine: peripheral edema, flushing. Verapamil: constipation, bradycardia, AV block. Statins: myalgia/myopathy, rhabdomyolysis (rare), elevated LFTs. Digoxin: bradycardia, AV block, visual disturbances (yellow-green halos), GI symptoms."]','A','Quick adverse effect associations: Thiazides → low K+, high uric acid. Loop diuretics → ototoxicity (furosemide at high IV doses). Verapamil → constipation. Amlodipine → ankle edema. Digoxin → yellow halos. Statins → muscle pain/rhabdomyolysis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
